  "goal_id": "plat-08-repo-permission-model",
  "version": 1,
  "tasks": [
    {
      "id": "inventory-permissions",
      "description": "Inventory current per-repo permissions",
      "action": "list_permissions",
      "target": "GitHub_org",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "GitHub API is accessible",
          "fact": "github_api_accessible",
          "established_by": "env"
        }
      ]
    },
    {
      "id": "define-team-structure",
      "description": "Define team structure and roles",
      "action": "define_structure",
      "target": "team_roles",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Current permissions inventory is available",
          "fact": "permissions_inventory_ready",
          "established_by": "inventory-permissions"
        }
      ]
    },
    {
      "id": "create-teams",
      "description": "Create teams and assign members",
      "action": "create_teams",
      "target": "GitHub_org",
      "risk_class": "high",
      "rollback": {
        "trigger": "team creation fails",
        "action": "revert to previous team structure",
        "safety_guard": "verify that no new teams were added"
      },
      "verification": {
        "what": "teams created successfully",
        "how": "check team list in GitHub",
        "expected": "new teams match the defined structure"
      },
      "preconditions": [
        {
          "description": "Team structure is defined",
          "fact": "team_structure_defined",
          "established_by": "define-team-structure"
