      "risk_class": "critical",
      "rollback": {
        "trigger": "permission application fails",
        "action": "restore legacy permissions",
        "safety_guard": "ensure legacy permissions are intact"
      },
      "verification": {
        "what": "repository permissions per team",
        "how": "check permission settings via GitHub API",
        "expected": "permissions reflect team-based structure"
      },
      "preconditions": [
        {
          "description": "Teams created successfully",
          "fact": "teams_created",
          "established_by": "create-teams"
        }
      ]
    },
    {
      "id": "enable-branch-protection",
      "description": "Enable branch protection rules",
      "action": "set_branch_protection",
      "target": "GitHub_repos",
      "risk_class": "high",
      "rollback": {
        "trigger": "branch protection fails",
        "action": "remove branch protection rules",
        "safety_guard": "audit branch settings are unchanged"
      },
      "verification": {
        "what": "branch protection rules status",
        "how": "query branch protection settings",
        "expected": "all branches have protection enabled as specified"
      },
      "preconditions": [
        {
          "description": "Team-based permissions are applied",
          "fact": "permissions_applied",
          "established_by": "apply-team-permissions"
        }
      ]
    },
    {
      "id": "verify-access",
      "description": "Verify access is correct per team",
      "action": "check_access",
      "target": "GitHub_org",
      "risk_class": "high",
      "rollback": {
        "trigger": "access verification fails",
        "action": "revert to last confirmed access settings",
        "safety_guard": "ensure access settings are logged"
      },
      "verification": {
        "what": "team access levels",
        "how": "generate access report",
        "expected": "team members have appropriate access"
      },
      "preconditions": [
        {
          "description": "Branch protection rules are enabled",
          "fact": "branch_protection_enabled",
          "established_by": "enable-branch-protection"
        }
      ]
    },
    {
      "id": "remove-legacy-permissions",
      "description": "Remove legacy per-repo permissions",
      "action": "remove_old_permissions",
      "target": "GitHub_org",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Team access verified",
          "fact": "access_verified",
          "established_by": "verify-access"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "inventory-permissions",
      "to_task": "define-team-structure",
      "kind": "hard"
    },
    {
      "from_task": "define-team-structure",
      "to_task": "create-teams",
      "kind": "hard"
    },
    {
      "from_task": "create-teams",
      "to_task": "apply-team-permissions",
      "kind": "hard"
    },
    {
      "from_task": "apply-team-permissions",
      "to_task": "enable-branch-protection",
      "kind": "hard"
    },
    {
      "from_task": "enable-branch-protection",
      "to_task": "verify-access",
      "kind": "hard"
    },
    {
      "from_task": "verify-access",
      "to_task": "remove-legacy-permissions",
      "kind": "hard"
    }
  ]
}
